from datetime import timedelta
from temporalio import activity, workflow
from temporalio.common import RetryPolicy

@activity.defn
async def summarise_claim(claim_id: str) -> str: ...          # model call

@activity.defn
async def release_payment(claim_id: str, key: str) -> str: ...  # sends Idempotency-Key

@workflow.defn
class CashlessClaim:
    def __init__(self) -> None:
        self.approved = False

    @workflow.signal
    def approve(self) -> None:                     # sent by the surveyor's app
        self.approved = True

    @workflow.run
    async def run(self, claim_id: str) -> str:
        summary = await workflow.execute_activity(
            summarise_claim, claim_id,
            start_to_close_timeout=timedelta(seconds=90),
            retry_policy=RetryPolicy(maximum_attempts=4, backoff_coefficient=2.0))
        await workflow.wait_condition(lambda: self.approved)   # can wait for days
        return await workflow.execute_activity(
            release_payment, args=[claim_id, f"pay-{claim_id}"],
            start_to_close_timeout=timedelta(seconds=30))
